/**
 * Prompt text lives in markdown, not in TypeScript template literals.
 *
 * Three times this session a backtick inside a prompt closed the template literal and broke
 * the build. The rule "don't use backticks" is a memory rule; moving the text out of the
 * language is a structural one: in a `.md` file a backtick is just a character.
 *
 * This script is the single direction of flow:
 *   packages/core/prompts/*.md  ->  packages/core/src/prompts.generated.ts
 * The generated file is committed so `tsc` works without running this first, and
 * `--check` fails when the two drift apart (health-check runs it).
 *
 *   node scripts/sync-prompts.mjs          # regenerate
 *   node scripts/sync-prompts.mjs --check  # fail if the generated file is stale
 */
import { readFileSync, writeFileSync, readdirSync, mkdirSync, existsSync } from 'node:fs';
import { join, basename } from 'node:path';

const ROOT = process.cwd();
const MD_DIR = join(ROOT, 'packages/core/prompts');
const OUT = join(ROOT, 'packages/core/src/prompts.generated.ts');
const check = process.argv.includes('--check');

/** markdown filename -> exported constant name */
const mapName = (file) => basename(file, '.md').replace(/-([a-z])/g, (_, ch) => ch.toUpperCase());

if (!existsSync(MD_DIR)) {
  console.error(`缺少 ${MD_DIR}`);
  process.exit(1);
}

const files = readdirSync(MD_DIR).filter((name) => name.endsWith('.md')).sort();
const parts = [
  '/**',
  ' * GENERATED by scripts/sync-prompts.mjs — do not edit.',
  ' * Source of truth: packages/core/prompts/*.md',
  ' */',
  '',
];
const names = [];
for (const file of files) {
  const name = mapName(file);
  names.push(name);
  const text = readFileSync(join(MD_DIR, file), 'utf8');
  // JSON.stringify keeps newlines, quotes and backticks as ordinary characters inside a
  // double-quoted literal, so the prompt text can no longer terminate a template string.
  parts.push(`export const ${name} = ${JSON.stringify(text)};`);
  parts.push('');
}
const content = parts.join('\n');

if (check) {
  const existing = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
  if (existing !== content) {
    console.error('prompts.generated.ts 与 packages/core/prompts/*.md 不一致：先跑 node scripts/sync-prompts.mjs');
    process.exit(1);
  }
  console.log(`prompts 同步（${names.length} 个文件）`);
  process.exit(0);
}

mkdirSync(join(ROOT, 'packages/core/src'), { recursive: true });
writeFileSync(OUT, content, 'utf8');
console.log(`generated ${names.length}: ${names.join(', ')}`);
